void TrafficLightMapVisualizerNode::binMapCallback(
  const autoware_map_msgs::msg::LaneletMapBin::ConstSharedPtr input_map_msg)
{
  lanelet::LaneletMapPtr viz_lanelet_map = autoware::experimental::lanelet2_utils::remove_const(
    autoware::experimental::lanelet2_utils::from_autoware_map_msgs(*input_map_msg));
  RCLCPP_DEBUG(get_logger(), "Map is loaded\n");

  // get lanelets etc to visualize
  lanelet::ConstLanelets all_lanelets = lanelet::utils::query::laneletLayer(viz_lanelet_map);
  aw_tl_reg_elems_ = lanelet::utils::query::autowareTrafficLights(all_lanelets);
}

lanelet::LaneletMapConstPtr from_autoware_map_msgs(
  const autoware_map_msgs::msg::LaneletMapBin & msg);

/**
 * @brief construct BasicLineString3d from vector of BasicPoint3d
 */
std::optional<lanelet::BasicLineString3d> create_safe_linestring(
  const std::vector<lanelet::BasicPoint3d> & points);

std::vector<lanelet::AutowareTrafficLightConstPtr> autowareTrafficLights(
  const lanelet::ConstLanelets & lanelets)
{
  std::vector<lanelet::AutowareTrafficLightConstPtr> tl_reg_elems;

  for (const auto & ll : lanelets) {
    std::vector<lanelet::AutowareTrafficLightConstPtr> ll_tl_re =
      ll.regulatoryElementsAs<lanelet::autoware::AutowareTrafficLight>();

    // insert unique tl into array
    for (const auto & tl_ptr : ll_tl_re) {
      lanelet::Id id = tl_ptr->id();
      bool unique_id = true;

      for (const auto & tl_reg_elem : tl_reg_elems) {
        if (id == tl_reg_elem->id()) {
          unique_id = false;
          break;
        }
      }

      if (unique_id) {
        tl_reg_elems.push_back(tl_ptr);
      }
    }
  }
  return tl_reg_elems;
}
